var CATALOG = [{"href": "newcomer-guide.html", "title": "Your Guide to School in the U.S.", "aud": "Students & families", "kind": "PDF guide · 5 languages", "desc": "For any K–12 student new to an American school: how schools work, enrolling, a school day, grades and graduation, legal rights and EL support, classroom culture, family tips and a 60-word glossary — English side by side with Spanish, Vietnamese, Arabic, Chinese or Haitian Creole. Free PDF in each language.", "section": "Students & families"}, {"href": "first-100-words.html", "title": "My First 100 Words at School", "aud": "Students", "kind": "Interactive · 100 words", "desc": "The words a newcomer hears in the first month — people, places, the schedule, teacher instructions, lunch, rules, grades and asking for help — ten groups of ten, with tap-to-hear pronunciation, two quiz modes, a progress counter and printable flashcards. Five languages.", "section": "Students & families"}, {"href": "storm-lens/", "title": "Storm Lens: Point. Name. Say.", "aud": "Students 9–12", "kind": "Camera app · 334 words", "desc": "Point the Chromebook camera at anything in the room and the room becomes the vocabulary list. Two recognition models run in the browser (80 objects live, 1,000 on scan) against a 334-word school bank; every word opens a card with Spanish, the cognate flag, four-lane sentence frames, a verb collocation, pronunciation coaching for Spanish speakers, plurals, a quick check, an ELPA21-style “describe the picture” speaking task and a write-it check — all speech-checked. The student's own photos become their word wall, four practice modes, scavenger missions and rolling end credits. Narrated like a film. Teachers get hunt links, a class view from student files, an exit ticket and a device check. Installs and works offline. No account, nothing uploaded.", "section": "Students & families"}, {"href": "english-on-your-own.html", "title": "English On Your Own", "aud": "Students & families", "kind": "Practice · 22 task types", "desc": "Built to the published ELPA21 grades 9–12 blueprint: all twenty-two task types — Listen and Match, Academic Debate, Short Conversation, Argument and Support Essay, Discrete Editing, Construct a Claim, Compare Pictures, Observe and Report and the rest — plus a sixty-item full practice form (23 listening, 26 reading, 5 writing, 6 speaking) that returns a level estimate per domain and an Emerging / Progressing / Proficient determination. Speaking records and checks what the student actually said; writing gets an automatic check and the rater's checklist. Directions in six languages. No account, no teacher needed.", "section": "Students & families"}, {"href": "graduation-roadmap.html", "title": "Graduation Roadmap for Newcomers", "aud": "Students 9–12", "kind": "Planner · 4 diploma paths", "desc": "Pick a diploma path (Traditional, CTE, Academic, Distinguished), type the credits you have and watch the meters, check off the four state tests, learn how home-country classes and your first language count, and fill in a four-year plan with your counselor. Five languages.", "section": "Students & families"}, {"href": "elpt-family-guide.html", "title": "The English Test, Explained for Families", "aud": "Families", "kind": "Explainer · 5 languages", "desc": "What the ELPT (ELPA21) is, the four domains, what Levels 1–5 actually mean, a sample score report decoded, the exit rule (Level 4 in all four), the EL year calendar, and what families can do at home — in five languages.", "section": "Students & families"}, {"href": "can-do-checklist.html", "title": "My English Can-Do Checklist", "aud": "Students 6–12", "kind": "Self-check · 80 statements", "desc": "Eighty “I can…” statements across listening, speaking, reading and writing at Levels 1–5. Students check what is true today, see an estimated level per skill, set a goal for each, and copy a summary for their teacher — a mirror of the ELPT they can use three times a year. Five languages.", "section": "Students & families"}, {"href": "sentence-lab.html", "title": "Sentence Lab: English Grammar in Real Life", "aud": "Students 9–12", "kind": "PDF packet · 25 pages", "desc": "Sixteen grammar features in realistic school scenes — subject and verb, pronouns, be, articles, plurals, adjectives, present, negatives, questions, right now, past, future plans, prepositions, connectors, sentence repair, expansion — with a Newcomer lane and a Progressing lane on every page. A shared writing project, a before/after six-skill check, and the full teacher key with a scoring rubric. Free 25-page PDF.", "section": "Students & families"}, {"href": "elpa21-practice-student.pdf", "title": "ELPA21 Task Practice · Student", "aud": "Grades 9–12", "kind": "PDF packet · 16 pages", "desc": "Sixteen pages of practice across all four domains, written in the format of the assessment: construct a claim, respond to a message, observe and report, state an opinion, follow instructions, academic lecture, informational set, short paragraph.", "section": "Students & families"}, {"href": "https://radan55.github.io/elpa21-reading-studio/", "title": "ELPA21 Reading Studio", "aud": "K–12", "kind": "Practice · 122 items", "desc": "Mississippi ELPT-style reading practice for English learners: six grade bands, 122 original items, eight item types, mock-test conditions, accommodations, bilingual supports, levels, badges and a teacher dashboard.", "section": "Students & families"}, {"href": "https://radan55.github.io/elpa21speaking01/", "title": "School Life • Language Lab", "aud": "9–12", "kind": "Practice · 25 activities", "desc": "Twenty-five four-skill ELPA21-style activities built around school-life scenarios: reading, listening, speaking and writing in the format students will see on the test.", "section": "Students & families"}, {"href": "https://radan55.github.io/el-publishing-grammar-songs/", "title": "Grammar Beats", "aud": "Music", "kind": "Music · 3 song lessons", "desc": "Radio-style grammar songs with full interactive lessons: nouns, adjectives and verbs, each with an audio track and a student lesson built to the beat.", "section": "Students & families"}, {"href": "https://radan55.github.io/tamales02/", "title": "How Tamales Are Made", "aud": "9–12", "kind": "Lesson · 1 text", "desc": "Feature article plus five interactive activities, vocabulary matching and a student progress report. The text behind the sample-lesson breakdown.", "section": "Students & families"}, {"href": "https://radan55.github.io/elstudentmagazine01/", "title": "Many Voices", "aud": "Students", "kind": "Magazine · Issue 1", "desc": "A magazine for multilingual high-school students: articles, interactive features, vocabulary tools and a teacher resource page.", "section": "Students & families"}, {"href": "content-teachers.html", "title": "For Content Teachers", "aud": "Content teachers", "kind": "Start here · 3 questions", "desc": "The front door for a teacher who teaches biology, math or history and has English learners in the room. Three questions — what do I do Monday, how do I grade them, am I allowed to change the test — each answered with a free tool, plus what the moves look like by subject, a spreadsheet of the resources sorted by when you need them, and the twelve things built for a content classroom.", "section": "Every classroom teacher"}, {"href": "cognate-hunt.html", "title": "Cognate Hunt", "aud": "Content teachers", "kind": "Tool · 373 pairs", "desc": "Paste tomorrow's reading — a biology paragraph, a history passage, a word problem — and every English–Spanish cognate lights up, so a content teacher can see at a glance how much of the text their Spanish speakers already own. Certain pairs (373 school words, science and history heaviest) get a solid line; pattern guesses (-tion → -ción) get a dotted one and say so; false friends — library, exit, once, realize — are flagged in red with what the Spanish word really means. Prints a cognate wall, copies as a list, sends nothing anywhere. The tool for Monday Move 10.", "section": "Every classroom teacher"}, {"href": "by-subject.html", "title": "By Subject & Grade", "aud": "Content teachers", "kind": "Grid · 16 squares", "desc": "Sixteen squares — English/ELA, mathematics, science and social studies crossed with K–2, 3–5, 6–8 and 9–12 — each naming what the language, not the content, asks of an English learner at that point, two moves from the Monday Moves series, and the hub resources that apply. Under every subject, twenty-seven free resources from elsewhere — the Library of Congress, Stanford, WIDA, PhET, the National Archives — each opened and checked before it was listed, with any free-account catch stated. Color-coded, narrowable to your band, printable.", "section": "Every classroom teacher"}, {"href": "sheltered.html", "title": "Sheltered: 12 Minutes as an English Learner", "aud": "Faculty PD", "kind": "Simulation · 12 minutes", "desc": "Take a real Biology, Algebra I or U.S. History lesson in a language you do not speak — Spanish, Vietnamese or Arabic — then take it again with the four lanes in place. Same language, same clock, parallel questions. Your two scores end up side by side, each support is named with the lane it serves, and the last screen finally tells you what the lesson said. Built to run with a whole faculty in twenty-five minutes.", "section": "Every classroom teacher"}, {"href": "el-assistants.html", "title": "EL Assistants for Content Teachers", "aud": "Teachers", "kind": "AI prompts · 4 assistants", "desc": "Four copy-and-paste assistants for the teacher who teaches biology, not English: scaffold a lesson by lane, level a text and prep the vocabulary, make a quiz measure content instead of English (Mississippi accommodations built in), and write to families in English and Spanish. Works in Claude, Gemini, ChatGPT or Copilot; no student names ever.", "section": "Every classroom teacher"}, {"href": "el-bridge.html", "title": "EL Bridge Mississippi", "aud": "Teachers", "kind": "Builder · K–12 + EOC", "desc": "Pick a Mississippi standard (K–12 ELA, math, science, or Algebra I, Biology I, English II), describe the lesson you already teach, and get it back in four lanes: Newcomer, Emerging, Progressing, Challenge. Also writes leveled texts with text-dependent questions and MAAP-style items with a linguistically accessible twin for every item. Builds the prompt, you run it in Claude, ChatGPT, Gemini or Copilot, paste the answer back, and it lays out the plan. No sign-up on this site.", "section": "Every classroom teacher"}, {"href": "https://radan55.github.io/el-field-guide/", "title": "The EL Field Guide", "aud": "All staff", "kind": "Field guide · Web guide", "desc": "Plain-language guide for general-education, special-education and administrative staff: identification, instruction, assessment and the legal obligations, with strategies you can use tomorrow.", "section": "Every classroom teacher"}, {"href": "sentence-frames.html", "title": "Sentence-Frame Bank", "aud": "Teachers", "kind": "Bank · 150 frames", "desc": "150 frames by language function — narrate, inform, explain, argue, classroom talk — and by level 1–5, each with a Spanish gloss. Filter to today's function and your students' levels, tick the ones you want, copy them into your slide.", "section": "Every classroom teacher"}, {"href": "spoken-spanish-english.html", "title": "Spoken Spanish & Spoken English", "aud": "Teachers", "kind": "PDF guide · 23 pages", "desc": "Shared strengths, different patterns: what the two languages share, where sounds and sentences differ, what you may hear in class and a helpful response for each. Phrase banks in English and Spanish by lane, a correct-now-or-later decision guide, three practice cases, a twelve-error table, and a first-week belonging routine. Free 23-page PDF.", "section": "Every classroom teacher"}, {"href": "accommodations-cards.html", "title": "EL Accommodations Quick Cards", "aud": "Teachers", "kind": "Quick cards · 18 cards", "desc": "Eighteen cards: what the accommodation is, who it fits, how to do it in class tomorrow, whether it is allowed on MAAP and ELPT, and the exact wording for the LSP. Filter by state-test-allowed, classroom-only, newcomer, reading, writing. Prints two-up.", "section": "Every classroom teacher"}, {"href": "sub-para.html", "title": "Substitute Card & Para Guide", "aud": "Subs · Paras · Tutors", "kind": "Printable · 2 pages", "desc": "A one-page “English learners in this room” card for the substitute (lane counts, allowed supports, what to do and not do, no names) and a one-page guide for the paraprofessional or tutor working one-on-one: eight moves, a 20-minute session, a log, Spanish phrases.", "section": "Every classroom teacher"}, {"href": "coteaching-plan.html", "title": "Co-Teaching Lesson Plan", "aud": "Teachers", "kind": "Planner · 1 page", "desc": "Content objective + language objective on one page, with a language-objective bank by subject and function, six co-teaching models, who-does-what, supports by lane, and separate assessments for content and language. Fills in the browser, prints on one page.", "section": "Every classroom teacher"}, {"href": "newcomer-k5.html", "title": "Elementary Newcomer Kit (K–5)", "aud": "Teachers K–5", "kind": "Kit · K–2 and 3–5", "desc": "The first ten days with a young newcomer, in two bands: what to get right each day, room setup, what transfers from the home language, and the printables for the desk tomorrow — picture-schedule and “I need” cards, 20 phrases, a family call script, a week-one show-me check. English and Spanish.", "section": "Every classroom teacher"}, {"href": "showcase.html", "title": "Showcase: Built by Teachers", "aud": "Teachers", "kind": "Gallery · Open submissions", "desc": "Real adaptations, leveled texts, and item sets Mississippi teachers made with EL Bridge and the Assistants and chose to share. Filter by subject, open the materials, add your own through the short form.", "section": "Every classroom teacher"}, {"href": "tech-radar.html", "title": "Six New Tech Tools for English Learners", "aud": "Teachers", "kind": "Radar · Updated weekly", "desc": "Verified this month: Gemini in Google Classroom student study tools (newest, Oct 6), Read Along in Google Classroom, SpeakingMonkey, MinuteMic, Brisk Boost and Google Translate Practice — what's new, what it costs, a four-lane classroom use for each, and a watch list.", "section": "Every classroom teacher"}, {"href": "language-bridge-2026-09.html", "title": "The Language Bridge", "aud": "Teachers", "kind": "Bulletin · Sept 2026", "desc": "A one-page bulletin for content teachers: five findings from acquisition research with a classroom move attached to each, the eight SIOP components translated for a content classroom, paired content and language objectives, and a compliance corner.", "section": "Every classroom teacher"}, {"href": "https://radan55.github.io/elpa21speaking01/october/", "title": "The Field Atlas", "aud": "Teachers", "kind": "Magazine · Oct 2026", "desc": "\"For the teacher who never planned to teach language.\" Sixteen plates on working with English learners in the general-education classroom.", "section": "Every classroom teacher"}, {"href": "https://radan55.github.io/everyteacherisalanguageteacher/", "title": "Every Teacher Is a Language Teacher", "aud": "PD", "kind": "PD module · 45–60 min", "desc": "Self-paced professional development for general- and special-education teachers: six sections on supporting English learners in any classroom.", "section": "Every classroom teacher"}, {"href": "https://radan55.github.io/RichardDaniel/language-functions/", "title": "36-Week Language Functions", "aud": "K–12", "kind": "Scope & sequence · 36 weeks · K–12", "desc": "Twelve language functions across four grade bands and four proficiency tiers: calendar themes, daily plans, texts with quizzes, a standards crosswalk, a sentence-frame ladder and a bilingual student tracker.", "section": "The EL teacher's desk"}, {"href": "https://radan55.github.io/RichardDaniel/curriculum-36/", "title": "36-Week EL Curriculum: Emerging + Progressing", "aud": "9–12", "kind": "Curriculum map · 36 weeks · 9–12", "desc": "One theme calendar, two language lanes. Eight units mapped week by week with grammar ladders, ELP and MS CCRS codes, writing products, ELPA21 mirror tasks, a 90-minute block template and an assessment calendar built back from the ELPT window — every recommendation tagged by evidence strength.", "section": "The EL teacher's desk"}, {"href": "sample-lesson.html", "title": "One Text. Four Lanes. Five Ways to Prove It.", "aud": "9–12", "kind": "Sample lesson · 90 minutes", "desc": "The 90-minute arc, the lane-by-lane differentiation and the reasoning behind a Storm Studio block, built on the How Tamales Are Made lesson. Read it before you run your first block.", "section": "The EL teacher's desk"}, {"href": "newcomer-week1.html", "title": "Newcomer Week 1 Kit", "aud": "Teachers", "kind": "Kit · 5 days", "desc": "The week a student arrives, hour by hour where it matters: the before-day-one checklist, the walkthrough script, the buddy brief, the family call, which Newcomer Series resource to use each day, and a day-5 exit ticket that tells you the week worked.", "section": "The EL teacher's desk"}, {"href": "lsp-builder.html", "title": "LSP Builder", "aud": "Teachers", "kind": "Generator · Mississippi LSP", "desc": "Enter the four ELPT levels and the Language Service Plan drafts itself: lane, services, program minutes, instructional and assessment accommodations, a goal with strategies and evidence for each domain, the test-coordinator note and the review note — every drafted field marked and editable, nothing you type ever overwritten — suggested from the level or chosen from an ELPA21 goal bank of 80 measurable goals, each tied to an ELP Standard. Every component a Mississippi LSP is expected to carry is on the form — the identification trail (Home Language Survey, screener and parent notification, each dated and checked against the 30-day clock), ELPT history by year, dual-identification coordination, grading and retention safeguards, nine-weeks reviews, four-year monitoring, the Student Evaluation Team signature block — and a live checklist says what is still missing before it goes for signatures. Print, or save as a file to reopen at review.", "section": "The EL teacher's desk"}, {"href": "newcomer-intake.html", "title": "Newcomer Intake", "aud": "Teachers", "kind": "Generator · 3 documents", "desc": "Type the student once; open the EL Student Profile, the Language Service Plan and the identification letter already filled in. Lane and overall determination compute as you type. Save the student as one file; reopen it at the semester review.", "section": "The EL teacher's desk"}, {"href": "student-profile.html", "title": "EL Student Profile", "aud": "Teachers", "kind": "Generator · 1 page", "desc": "Type the ELPT levels and a few facts; get the one page a sub or a new content teacher needs — what the student can do in each domain, the lane, what helps every day, strengths, watch-fors, LSP accommodations, and who to call. For the sub folder.", "section": "The EL teacher's desk"}, {"href": "field-notes.html", "title": "What's New in Teaching English Learners", "aud": "Research brief", "kind": "Research brief · Oct 2026", "desc": "Eight ideas shaping 2026 — Science of Reading \"yes AND,\" cross-linguistic transfer, Key Language Uses, newcomer programs, co-teaching, AI, and Mississippi's four-domain exit — each tagged by evidence strength, with sources.", "section": "The EL teacher's desk"}, {"href": "elpa21-practice-teacher.pdf", "title": "ELPA21 Task Practice · Teacher", "aud": "Teacher edition", "kind": "PDF packet · Teacher edition", "desc": "The teacher edition: read-aloud scripts, question sets, proficiency look-fors at Emerging and Progressing, a four-lane version of every task from Newcomer to Challenge, answer keys and a two-axis scoring guide.", "section": "The EL teacher's desk"}, {"href": "https://radan55.github.io/mselablueprintinfo01/", "title": "The Blueprint / El Plano", "aud": "K–12", "kind": "Curriculum · K–12 · EN/ES", "desc": "Bilingual guide to the Mississippi ELA standard blueprints: grade-by-grade reviews, practice passages and test-style items, Grammar Beats songs, four-lane supports, family pages and a lesson builder.", "section": "The EL teacher's desk"}, {"href": "https://radan55.github.io/msellibrary/", "title": "The Mississippi EL Library", "aud": "5 volumes", "kind": "Library · 5 volumes", "desc": "A free five-volume resource system for English-learner success in Mississippi schools: the shelf every EL teacher and coordinator in the state should have open.", "section": "The EL teacher's desk"}, {"href": "https://radan55.github.io/elvocabularycurriculumengine/", "title": "The Vocabulary Engine", "aud": "ELPA21", "kind": "PDF · 5-day cycle", "desc": "A five-day instructional cycle for academic vocabulary, with PD modules, ELPA21-aligned activities and reproducible student handouts as a free PDF.", "section": "The EL teacher's desk"}, {"href": "https://radan55.github.io/hispanicheritagemonth2026/", "title": "Hispanic Heritage: 30 People", "aud": "Heritage", "kind": "Unit · 30 profiles", "desc": "Bilingual biography profiles of thirty Hispanic figures with discussion prompts and classroom projects. Featured below.", "section": "The EL teacher's desk"}, {"href": "https://radan55.github.io/ms-el-command-center/", "title": "MS EL Command Center", "aud": "Compliance", "kind": "Reference app · Mississippi", "desc": "The Mississippi EL teacher's reference hub: identification timelines, ELPA21 procedures, service plans, MTAM accommodations, §15 accountability and the documentation to prove it.", "section": "The EL teacher's desk"}, {"href": "leaders.html", "title": "For District Leaders", "aud": "Administrators", "kind": "Start here · 3 questions", "desc": "Are we compliant? Are our ELs growing? What does it cost? The front door for superintendents, federal programs directors, and EL coordinators: a two-week path, a program-at-a-glance strip that fills from your own numbers, and every district-office tool in one place.", "section": "District & compliance"}, {"href": "el-evaluate.html", "title": "Evaluate Your Own EL Program", "aud": "District leaders", "kind": "Course · 6 sessions", "desc": "The method a consulting firm sells, written out so your own team can run it: frame the question, send the data request (copy it as written), check who is in the program, read growth against years-in-program, compare current ELs to former ELs to never-ELs, then find the cause and write the one-page board memo. Each session has the reading thresholds, the red flags, a worked example, and a deliverable that saves as you type and prints as one findings report.", "section": "District & compliance"}, {"href": "el-audit.html", "title": "EL Program Self-Audit", "aud": "Administrators", "kind": "Self-audit · 33 items · 1 hour", "desc": "Thirty-three items from Castañeda, Title VI, the EEOA, ESSA Title III, and the February 2026 accommodations manual. Scored live, legal gaps in red, and a printable corrective-action plan with owners, dates, and the authority for each item. Nothing leaves your browser.", "section": "District & compliance"}, {"href": "el-outcomes.html", "title": "EL Outcomes Dashboard", "aud": "Administrators", "kind": "Dashboard · 5 charts", "desc": "Enter counts, not names, and get the annual evaluation Castañeda asks for: ELPT level distribution, growth and exit, participation against the 95% rule, the achievement and graduation gap for current and former ELs, the three-year trend, and a board paragraph written from your numbers.", "section": "District & compliance"}, {"href": "el-compliance-calendar.html", "title": "EL Program Compliance Calendar", "aud": "Administrators", "kind": "Checklist · 45 items", "desc": "Forty-five obligations placed in the month they come due — HLS and 30-day screening, parent notices, Language Service Plans, ELPT window, exit and four-year monitoring, Title III, MSIS coding, accommodations, the annual program evaluation — each tagged federal, Mississippi or best practice, with the standing Castañeda, Lau and Plyler duties up top. Check off, save, print.", "section": "District & compliance"}, {"href": "title3-planner.html", "title": "Title III Funding Planner", "aud": "Administrators", "kind": "Fiscal planner · ESSA §3115", "desc": "Estimate the subgrant, split it across the three required activities, check the 2 percent administrative cap and the supplement-not-supplant pattern, and see what the district owes anyway if the House FY2027 bill ends Title III.", "section": "District & compliance"}, {"href": "parent-letters.html", "title": "EL Parent Notification Letters", "aud": "Administrators", "kind": "Templates · 6 letters", "desc": "Six letters every program sends, written to ESSA §1112(e)(3): initial identification and placement with every required element, annual continuing notice, exit, monitoring notice, parent refusal form, and meeting invitation. Fill in the student once; print the English and Spanish pages together.", "section": "District & compliance"}, {"href": "board-brief.html", "title": "Board Brief & Deck", "aud": "Administrators", "kind": "Template · 1 page + .pptx", "desc": "“The State of English Learners in [District]”: a dozen numbers and three recommendations become a one-page executive brief in board language, plus a matching eight-slide PowerPoint template with speaker notes and a decision requested.", "section": "District & compliance"}, {"href": "el-data-dashboard.html", "title": "EL Data Dashboard", "aud": "Administrators", "kind": "Excel template · 8 tables", "desc": "Paste your ELPT roster; get overall determination, domain averages, level distribution, growth, years in program, lowest domain, by-grade proficiency and home-language counts — eight formula-driven tables and three charts for the board, Title III and Castañeda prong three.", "section": "District & compliance"}, {"href": "policy-brief.html", "title": "Mississippi EL Policy Brief", "aud": "Administrators", "kind": "Monthly brief · Oct 2026", "desc": "One page a month for superintendents, federal programs directors, and EL coordinators: what changed at MDE, in Congress, at the U.S. Department of Education, and in the courts; what it means for a district of about 2,000 students; what to do and by when. A board-ready paragraph to copy, dates ahead, a watch list, and the primary source on every item. October 2026: OELA's closure, the House FY27 bill that zeroes Title III, and Mississippi's 2026–27 ELPT rules.", "section": "District & compliance"}, {"href": "case-studies.html", "title": "EL Case Studies", "aud": "Administrators", "kind": "Cases · 3 cases", "desc": "A newcomer’s first ninety days, the eighth grader stuck one ELPT domain short of exit, and a district with six weeks before the monitor arrives. Composite cases from Mississippi patterns, with the hub tool and the cost named at every step.", "section": "District & compliance"}, {"href": "district-kit.html", "title": "District Partnership Kit", "aud": "Administrators", "kind": "Kit · 90 days", "desc": "What a 90-day engagement delivers to a district with one EL teacher and no coordinator: the audit, the letters, the LSPs, the newcomer flow, the staff module, the dashboard, and the board brief, built on your numbers and letterhead. You keep everything.", "section": "District & compliance"}, {"href": "fact-check.html", "title": "Mississippi Fact-Check", "aud": "Administrators", "kind": "Review record · 24 claims", "desc": "Every Mississippi-specific claim on the hub — credits, endorsements, ELPT window, exit rule, monitoring, screening deadlines, test accommodations, Seal of Biliteracy — in one table with its status (14 verified, 5 corrected, 5 for the district to confirm), the source, and a sign-off line for the Title III director.", "section": "District & compliance"}, {"href": "https://radan55.github.io/elpublishing-magazineeditionone/#compliance", "title": "Making Them Count", "aud": "Book", "kind": "Book · Issue One", "desc": "Teaching English Learners in Mississippi's Overlooked Districts. A field manual for small districts with big obligations, published in the 2026 Educator Edition.", "section": "District & compliance"}];

